        fs::write(fx.work.join("fix.txt"), "a review fix\n").expect("write");
        fs::write(fx.bot.join("tail.jsonl"), "{\"line\":2}\n").expect("write");

        run(&fx, both(), None).expect("squash");

        assert!(files(&fx.work, "@-").contains("fix.txt"));
        let after = jj_ok(
